2	//!
3	//! Provides functionality for cloning and updating git repositories
4	//! to fetch templates, with support for specific refs and update detection.
5	
6	use anyhow::{bail, Result};
7	use sha2::{Digest, Sha256};
8	use std::path::{Path, PathBuf};
9	
10	/// Allowed URL schemes for git clone operations.
11	///
12	/// Only secure transport protocols are permitted as defense-in-depth:
13	/// - `https://` -- encrypted HTTP transport
14	/// - `ssh://` -- SSH transport
15	/// - `git://` -- native git protocol
16	/// - `git@` -- SCP-style SSH shorthand (e.g. `git@github.com:org/repo.git`)
17	///
18	/// Rejected schemes include `file://` (local filesystem access), `ftp://`,
19	/// and plain `http://` (unencrypted, vulnerable to MITM).
20	pub fn validate_git_url(url: &str) -> Result<()> {
21	    // SCP-style shorthand: git@host:path
22	    if url.starts_with("git@") {
23	        return Ok(());
24	    }
25	
26	    const ALLOWED_SCHEMES: &[&str] = &["https://", "ssh://", "git://"];
27	
28	    for scheme in ALLOWED_SCHEMES {
29	        if url.starts_with(scheme) {
30	            return Ok(());
31	        }
32	    }
33	
34	    bail!(
35	        "Unsupported git URL scheme: {url}\n\
36	         Allowed schemes: https://, ssh://, git://, and git@ (SCP-style shorthand)"
37	    );
38	}
