68	    /// Clone or update a repository.
69	    ///
70	    /// Validates the URL scheme before proceeding. Only `https://`, `ssh://`,
71	    /// `git://`, and `git@` SCP-style URLs are allowed.
72	    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
