1	//! Comprehensive system tests for `bivvy cache`.
2	//!
3	//! Tests cache management subcommands: `list`, `stats`, `clear`, and their
4	//! flag variants.  Each test is isolated by setting `HOME` and
5	//! `XDG_CACHE_HOME` to a temp directory so the cache is deterministic.
6	//!
7	//! When a test needs a non-empty cache, it seeds entries directly through
8	//! `bivvy::cache::CacheStore` pointing at the same isolated directory the
9	//! spawned binary will read from.
10	#![cfg(unix)]
11	
12	mod system;
13	
14	use assert_cmd::cargo::cargo_bin;
15	use bivvy::cache::CacheStore;
16	use expectrl::Session;
17	use std::path::{Path, PathBuf};
18	use std::process::Command;
