23	// ─────────────────────────────────────────────────────────────────────
24	// Helpers
25	// ─────────────────────────────────────────────────────────────────────
26	
27	/// Compute the cache directory that a child `bivvy` process will use when
28	/// spawned with the given `HOME` and `XDG_CACHE_HOME` set to `home`.
29	///
30	/// This mirrors `bivvy::cache::default_cache_dir()` on both macOS and
31	/// Linux so tests can seed entries the binary will actually read.
32	fn isolated_cache_dir(home: &Path) -> PathBuf {
33	    // On macOS `dirs::cache_dir()` returns `$HOME/Library/Caches`; on Linux
34	    // it reads `$XDG_CACHE_HOME` first, falling back to `$HOME/.cache`.
35	    // We set both env vars in `spawn_cache_isolated`, and since
36	    // `XDG_CACHE_HOME` takes precedence on Linux, we use it as the base
37	    // there.  On macOS `XDG_CACHE_HOME` is ignored, so we use
38	    // `Library/Caches` directly.
39	    #[cfg(target_os = "macos")]
40	    {
41	        home.join("Library")
42	            .join("Caches")
43	            .join("bivvy")
44	            .join("templates")
45	    }
46	    #[cfg(not(target_os = "macos"))]
47	    {
48	        home.join("bivvy").join("templates")
49	    }
50	}
51	
52	/// Build a `CacheStore` pointing at the isolated cache dir for `home`.
53	fn isolated_store(home: &Path) -> CacheStore {
54	    let dir = isolated_cache_dir(home);
55	    std::fs::create_dir_all(&dir).unwrap();
56	    CacheStore::new(dir)
57	}
58	
59	/// Spawn `bivvy` in a PTY with `HOME` and `XDG_CACHE_HOME` overridden.
60	///
61	/// This isolates the cache from the user's real `~/.cache/bivvy/` (or
62	/// `~/Library/Caches/bivvy/` on macOS), giving each test a
63	/// deterministically empty cache — or a deterministically seeded one
64	/// when combined with [`isolated_store`].
65	fn spawn_cache_isolated(args: &[&str], home: &Path) -> Session {
66	    let bin = cargo_bin("bivvy");
67	    let mut cmd = Command::new(bin);
68	    cmd.args(args);
69	    cmd.env("HOME", home);
70	    // On Linux, `dirs::cache_dir()` honours XDG_CACHE_HOME first. Point it
71	    // directly at the temp home so Linux tests are as isolated as macOS.
72	    cmd.env("XDG_CACHE_HOME", home);
73	    // Clear anything that could leak the real user's cache.
74	    cmd.env_remove("XDG_DATA_HOME");
75	    let mut session = Session::spawn(cmd).expect("Failed to spawn bivvy");
76	    session.set_expect_timeout(Some(Duration::from_secs(30)));
77	    session
78	}
79	
80	/// Run `bivvy cache <subcommand>` non-interactively under the isolated
81	/// environment and return `(stdout, stderr, exit_code)`.
82	///
83	/// Used for help / error tests where we want deterministic captured
84	/// output suitable for snapshotting.
85	fn run_cache_isolated(args: &[&str], home: &Path) -> (String, String, i32) {
86	    let bin = cargo_bin("bivvy");
87	    let output = Command::new(bin)
88	        .args(args)
89	        .env("HOME", home)
90	        .env("XDG_CACHE_HOME", home)
91	        .env_remove("XDG_DATA_HOME")
92	        .output()
93	        .expect("Failed to run bivvy");
94	    let stdout = strip_ansi(&String::from_utf8_lossy(&output.stdout));
95	    let stderr = strip_ansi(&String::from_utf8_lossy(&output.stderr));
96	    let code = output.status.code().unwrap_or(-1);
97	    (stdout, stderr, code)
98	}
