use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Write data to a file atomically by writing to a temporary file first,
/// then renaming into place. This prevents concurrent readers from seeing
/// partially-written content when multiple processes access the cache.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let tmp_name = format!(
        "{}.{}.tmp",
        path.file_name()
            .unwrap_or_default()
            .to_string_lossy(),
        std::process::id(),
    );
    let tmp_path = path.with_file_name(tmp_name);

    fs::write(&tmp_path, data)
        .with_context(|| format!("Failed to write temp file {:?}", tmp_path))?;

    fs::rename(&tmp_path, path).with_context(|| {
        format!("Failed to rename {:?} to {:?}", tmp_path, path)
    })?;

    Ok(())
}

